async function request(suffix,options={}){const value=await api(path().replace('/admin/api/workflow-workspaces','/admin/api/v2/workspace-panels')+'/release-v2'+suffix,{...options,silent:true});if(!value.ok||value.profile!==PROFILE)throw Error();return value;}
function failure(error){if([401,403,404].includes(error.status)||!scopeIdentity()){clear();open.hidden=true;return;}status.textContent='요청 결과를 확인하지 못했습니다. 변경을 반복하기 전에 이력을 확인하세요.';}
async function load(){if(!scope)return;const m=mark();busy=true;controls();try{await request('/options');if(!valid(m))return;const tests=await api(path().replace('/admin/api/v2/workspace-panels','/admin/api/workflow-workspaces')+'/execution/runs',{silent:true});if(!valid(m))return;runs.replaceChildren();runs.dataset.rows=JSON.stringify(tests.runs);for(const run of tests.runs)runs.add(new Option(run.status+' · '+new Date(run.created*1000).toLocaleString(),run.id));const listed=await request('/releases');if(!valid(m))return;releaseId=releases.value;releases.replaceChildren();for(const release of listed.releases.filter(value=>value.active&&value.expires*1000>Date.now()))releases.add(new Option('Release · '+new Date(release.created*1000).toLocaleString()+' · revision '+release.revision,release.id));if([...releases.options].some(value=>value.value===releaseId))releases.value=releaseId;releases.dataset.rows=JSON.stringify(listed.releases);await loadDeployments(m);const view=await api('/admin/api/v2/workspace-panels/'+scope.workspace_id+'/lifecycle/preview',{silent:true});if(!valid(m))return;lifecycle.textContent='Expired unused tickets: '+view.expired_unused_tickets+'\nOld terminal outputs: '+view.old_terminal_outputs+'\nUnknown runs retained: '+view.unknown_runs_retained;status.textContent='현재 소유자 관리 항목을 조회했습니다. 에이전트 호출은 없습니다.';}catch(error){if(valid(m))failure(error);}finally{if(valid(m)){busy=false;controls();}}}
async function createRelease(){if(busy||!runs.value)return;const m=mark();busy=true;controls();try{await request('/releases',{method:'POST',json:{run_id:runs.value,ttl_seconds:Number(ttl.value)}});if(valid(m))await load();}catch(error){if(valid(m))failure(error);}finally{if(valid(m)){busy=false;controls();}}}
async function loadDeployments(m=mark()){deployments.replaceChildren();if(!releases.value)return;const response=await request('/releases/'+releases.value+'/deployments');if(!valid(m))return;for(const item of response.deployments){const row=make('div');row.className='adm-card';row.append(make('p','Deployment · revision '+item.revision+' · '+(item.active?'active':'revoked')+' · '+item.allowed_origins.join(', ')));if(item.active){const download=make('button','SDK 2 ZIP 다운로드');download.className='adm-btn';download.addEventListener('click',()=>downloadPackage(item.app_id));const revoke=make('button','배포 권한 철회');revoke.className='adm-btn';revoke.addEventListener('click',()=>revokeDeployment(item));row.append(download,revoke);}deployments.append(row);}}
async function issueGrant(){if(busy||!consent.checked||!releases.value)return;const m=mark(),body={allowed_origins:origins.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean),ttl_seconds:Number(grantTtl.value),minute_limit:Number(minutes.value),day_limit:Number(days.value),authorized:true,notice:'workspace-sdk-deployment-v2'};consent.checked=false;busy=true;controls();try{await request('/releases/'+releases.value+'/deployments',{method:'POST',json:body});if(valid(m)){await loadDeployments(m);status.textContent='Deployment issued. Customers still need current sign-in, explicit workspace access and fresh consent for every run.';}}catch(error){if(valid(m))failure(error);}finally{if(valid(m)){busy=false;controls();}}}
