async function maintainRuns(){if(busy||!confirm('Prune up to20 expired unused tickets and archive up to20 old terminal outputs? Unknown runs and signed replay records remain.'))return;const m=mark();busy=true;controls();try{await api('/admin/api/v2/workspace-panels/'+scope.workspace_id+'/lifecycle/maintain',{method:'POST',json:{limit:20},silent:true});if(valid(m))await load();}catch(error){if(valid(m))failure(error);}finally{if(valid(m)){busy=false;controls();}}}
