runs.addEventListener('change',controls);for(const field of [origins,minutes,days,grantTtl,releases])field.addEventListener('input',()=>{consent.checked=false;controls();});releases.addEventListener('change',()=>loadDeployments());consent.addEventListener('change',controls);restoreConsent.addEventListener('change',controls);close.addEventListener('click',clear);dialog.addEventListener('cancel',event=>{event.preventDefault();clear();});open.addEventListener('click',()=>{if(!scope?.can_manage)return;user=identity();decorate(dialog);dialog.showModal();load();});return {open: async value=>{select(value);user=identity();decorate(dialog);dialog.showModal();await load();}, leave:()=>{clear();dialog.remove();scope=null;}};
